    variants = []
    for flip in (False, True):
        for rot in range(4):
            pts=[]
            for r,c in template:
                x,y=(r,-c) if flip else (r,c)
                for _ in range(rot): x,y=y,-x
                pts.append((x,y))
            r0=min(r for r,c in pts); c0=min(c for r,c in pts)
            variants.append({(r-r0,c-c0) for r,c in pts})
